-/// Checkpoint-capable stack. This correctness-first fallback stores every frame eagerly.
+struct Checkpoint;
+
+namespace stack_detail
+{
+/// Stack items live in pages of four items; a page table maps page numbers to pages.
+/// Checkpoints share the page table of the live stack, and the live stack copies the table and
+/// individual pages on first write (copy-on-write). Tables and pages are carved out of the stack
+/// space of the owning execution state and fall back to the heap only when it is exhausted.
+inline constexpr size_t page_shift = 2;
+inline constexpr size_t page_items = size_t{1} << page_shift;
+inline constexpr size_t page_mask = page_items - 1;
+inline constexpr size_t block_words = page_items * 4;  ///< one block holds one page (128 bytes)
+inline constexpr size_t block_bytes = block_words * 8;
+inline constexpr size_t max_blocks = 1024;             ///< 4096 stack items
+inline constexpr size_t bitmap_words = max_blocks / 64;
+inline constexpr size_t table_hdr = 2;                 ///< words: refcount, used | cap << 32
+inline constexpr size_t table_classes = 7;             ///< arena tables span 1 << class blocks
+inline constexpr size_t ring_size = 8;
+inline constexpr uint64_t heap_class = table_classes;
+
+/// Page table layout (64-bit words): [0] reference count, [1] used entries | capacity << 32 |
+/// class << 56, then the page pointers. A flat block (flat_bit set) instead holds `used` items. Bookkeeping stored inside the stack space is accessed
+/// through uint64_t words, the type intx uses for the items themselves.
+inline uint64_t* entries(uint64_t* t) noexcept { return t + table_hdr; }
+inline const uint64_t* entries(const uint64_t* t) noexcept { return t + table_hdr; }
+inline size_t used(const uint64_t* t) noexcept { return static_cast<uint32_t>(t[1]); }
+inline size_t capacity(const uint64_t* t) noexcept { return (t[1] >> 32) & 0x7fffff; }
+inline constexpr uint64_t flat_bit = uint64_t{1} << 55;  ///< block holds items, not page pointers
+inline bool is_flat(const uint64_t* t) noexcept { return (t[1] & flat_bit) != 0; }
+inline constexpr size_t flat_max = 63;                  ///< deeper stacks are shared, not copied
+inline uint64_t table_class(const uint64_t* t) noexcept { return t[1] >> 56; }
+inline void set_used(uint64_t* t, size_t n) noexcept { t[1] = (t[1] & ~uint64_t{0xffffffff}) | n; }
+inline constexpr size_t class_capacity(size_t c) noexcept { return (block_words << c) - table_hdr; }
+inline uint256* page_at(uint64_t entry) noexcept { return reinterpret_cast<uint256*>(entry); }
+inline uint64_t entry_of(const uint256* page) noexcept { return reinterpret_cast<uint64_t>(page); }
+inline const uint256* flat_items(const uint64_t* t) noexcept
+{
+    return reinterpret_cast<const uint256*>(entries(t));
+}
+/// Item p (counted from the bottom) of a page table or flat block.
+inline const uint256& item_at(const uint64_t* t, size_t p) noexcept
+{
+    if (is_flat(t))
+        return flat_items(t)[p];
+    return page_at(entries(t)[p >> page_shift])[p & page_mask];
+}
+
+/// Block allocator over the stack space with heap fallback.
+struct Pool
+{
+    uint64_t* arena = nullptr;
+    size_t nblocks = 0;
+    size_t lo = 0;            ///< single blocks are carved upwards from here
+    size_t hi = 0;            ///< multi-block tables are carved downwards from here
+    uint64_t free1 = 0;       ///< free single blocks (index + 1, linked through word 0)
+    uint64_t tfree[table_classes] = {};
+    uint64_t page_bits[bitmap_words] = {};   ///< arena blocks holding pages
+    uint64_t* heap_tables = nullptr;         ///< heap tables, linked through word [-1]
+    uint256* heap_pages = nullptr;           ///< heap pages, linked through their header item
+    uint256* ring[ring_size] = {};           ///< recently replaced pages, kept for open references
+    size_t ring_pos = 0;
+    size_t gc_wait = 0;
+
+    bool in_arena(uint64_t p) const noexcept
+    {
+        return arena != nullptr && p - reinterpret_cast<uint64_t>(arena) < nblocks * block_bytes;
+    }
+    size_t block_of(uint64_t p) const noexcept
+    {
+        return (p - reinterpret_cast<uint64_t>(arena)) / block_bytes;
+    }
+    uint64_t* block(size_t b) const noexcept { return arena + b * block_words; }
+
+    /// Takes 1 << cls contiguous arena blocks.
+    bool take(size_t cls, size_t& b) noexcept
+    {
+        if (cls == 0)
+        {
+            if (free1 != 0)
+            {
+                b = free1 - 1;
+                free1 = block(b)[0];
+                return true;
+            }
+            if (lo < hi)
+            {
+                b = lo++;
+                return true;
+            }
+            return false;
+        }
+        if (tfree[cls] != 0)
+        {
+            b = tfree[cls] - 1;
+            tfree[cls] = block(b)[0];
+            return true;
+        }
+        const size_t n = size_t{1} << cls;
+        if (hi - lo >= n)
+        {
+            hi -= n;
+            b = hi;
+            return true;
+        }
+        return false;
+    }
+
+    void give(size_t cls, size_t b) noexcept
+    {
+        uint64_t& head = cls == 0 ? free1 : tfree[cls];
+        block(b)[0] = head;
+        head = b + 1;
+    }
+
+    uint64_t* new_table(size_t need)
+    {
+        size_t cls = 0;
+        while (cls < table_classes && class_capacity(cls) < need)
+            ++cls;
+        size_t b = 0;
+        uint64_t* t = nullptr;
+        if (arena != nullptr && cls < table_classes && take(cls, b))
+        {
+            t = block(b);
+            t[1] = (uint64_t{cls} << 56) | (uint64_t{class_capacity(cls)} << 32);
+        }
+        else
+        {
+            const size_t cap = need < class_capacity(0) ? class_capacity(0) : need;
+            uint64_t* raw = new uint64_t[1 + table_hdr + cap];
+            raw[0] = reinterpret_cast<uint64_t>(heap_tables);
+            heap_tables = raw;
+            t = raw + 1;
+            t[1] = (heap_class << 56) | (uint64_t{cap} << 32);
+        }
+        t[0] = 1;
+        return t;
+    }
+
+    void release(uint64_t* t) noexcept
+    {
+        if (--t[0] != 0)
+            return;
+        const uint64_t cls = table_class(t);
+        if (cls == heap_class)
+        {
+            uint64_t* raw = t - 1;
+            uint64_t** link = &heap_tables;
+            while (*link != raw)
+                link = reinterpret_cast<uint64_t**>(*link);
+            *link = reinterpret_cast<uint64_t*>(raw[0]);
+            delete[] raw;
+            return;
+        }
+        give(cls, block_of(reinterpret_cast<uint64_t>(t)));
+    }
+
+    uint256* heap_page()
+    {
+        uint256* raw = new uint256[page_items + 1];
+        raw[0][0] = reinterpret_cast<uint64_t>(heap_pages);
+        raw[0][1] = 0;
+        heap_pages = raw;
+        return raw + 1;
+    }
+
+    void remember(uint256* old) noexcept
+    {
+        ring[ring_pos] = old;
+        ring_pos = (ring_pos + 1) % ring_size;
+    }
+
+    /// Releases every heap allocation; arena memory goes away with the execution state.
+    void free_heap() noexcept
+    {
+        while (heap_tables != nullptr)
+        {
+            uint64_t* raw = heap_tables;
+            heap_tables = reinterpret_cast<uint64_t*>(raw[0]);
+            delete[] raw;
+        }
+        while (heap_pages != nullptr)
+        {
+            uint256* raw = heap_pages;
+            heap_pages = reinterpret_cast<uint256*>(raw[0][0]);
+            delete[] raw;
+        }
+    }
+};
+}  // namespace stack_detail
