+    }
+
+    void clear_owned() noexcept
+    {
+        for (auto& w : owned_)
+            w = 0;
+    }
+
+    inline void link(Checkpoint& cp) noexcept;
+    inline void commit_pending() noexcept;
+    inline void unlink(Checkpoint& cp) noexcept;
+    inline void relink(Checkpoint& from, Checkpoint& to) noexcept;
+    inline void adopt(Checkpoint& cp) noexcept;
+    inline void forget(Checkpoint& cp) noexcept;
+    inline void disown_all() noexcept;
+    inline size_t collect() noexcept;
+
+    uint256* new_page()
+    {
+        if (pool_.arena != nullptr)
+        {
+            size_t b = 0;
+            bool ok = pool_.take(0, b);
+            if (!ok)
+            {
+                if (pool_.gc_wait == 0)
+                {
+                    if (collect() < 8)
+                        pool_.gc_wait = 64;
+                }
+                else
+                    --pool_.gc_wait;
+                ok = pool_.take(0, b);
+            }
+            if (ok)
+            {
+                pool_.page_bits[b / 64] |= uint64_t{1} << (b % 64);
+                return reinterpret_cast<uint256*>(pool_.block(b));
+            }
+        }
+        return pool_.heap_page();
+    }
+
+    /// Gives the live stack a table of its own.
+    void unshare()
+    {
+        shared_ = false;
+        wend_ = 0;
+        fend_ = 0;
+        clear_owned();
+        if (tbl_ != nullptr && tbl_[0] > 1)
+        {
+            const size_t n = stack_detail::used(tbl_);
+            uint64_t* t = pool_.new_table(n);
+            uint64_t* e = stack_detail::entries(t);
+            for (size_t i = 0; i < n; ++i)
+                e[i] = ents_[i];
+            stack_detail::set_used(t, n);
+            --tbl_[0];
+            tbl_ = t;
+            ents_ = e;
+        }
+    }
+
+    void grow_table(size_t need)
+    {
+        const size_t n = tbl_ != nullptr ? stack_detail::used(tbl_) : 0;
+        uint64_t* t = pool_.new_table(need > 2 * n ? need : 2 * n);
+        uint64_t* e = stack_detail::entries(t);
+        for (size_t i = 0; i < n; ++i)
+            e[i] = ents_[i];
+        stack_detail::set_used(t, n);
+        if (tbl_ != nullptr)
+            pool_.release(tbl_);
+        tbl_ = t;
+        ents_ = e;
+    }
+
+    /// Grows the writable prefix over owned pages.
+    void extend_window() noexcept
+    {
+        const size_t n = stack_detail::used(tbl_);
+        size_t p = wend_ >> stack_detail::page_shift;
+        while (p < n && owned(p))
+            ++p;
+        wend_ = p << stack_detail::page_shift;
+    }
+
+    /// Makes page pi exist in the live table and be exclusively owned by it.
+    void own_page(size_t pi)
+    {
+        if (pending_ != nullptr)
+            commit_pending();
+        if (shared_)
+            unshare();
+        const size_t n = tbl_ != nullptr ? stack_detail::used(tbl_) : 0;
+        if (pi >= n)
+        {
+            // Pages are added in batches (bounded by the table capacity, so that table copies
+            // keep their size class) so that pushes rarely leave the fast path.
+            if (tbl_ == nullptr || pi >= stack_detail::capacity(tbl_))
+                grow_table(pi + 1);
+            size_t target = n < 4 ? 8 : 2 * n;
+            const size_t cap = stack_detail::capacity(tbl_);
+            if (target > cap)
+                target = cap;
+            if (target > stack_detail::max_blocks)
+                target = stack_detail::max_blocks;
+            if (target <= pi)
+                target = pi + 1;
+            for (size_t i = n; i < target; ++i)
+            {
+                ents_[i] = stack_detail::entry_of(new_page());
+                stack_detail::set_used(tbl_, i + 1);
+                set_owned(i);
+            }
+        }
+        else if (!owned(pi))
+        {
+            uint256* old = stack_detail::page_at(ents_[pi]);
+            uint256* p = new_page();
+            for (size_t k = 0; k < stack_detail::page_items; ++k)
+                p[k] = old[k];
