+inline void StackTop::link(Checkpoint& cp) noexcept
+{
+    cp.prev_ = nullptr;
+    cp.next_ = cps_;
+    if (cps_ != nullptr)
+        cps_->prev_ = &cp;
+    cps_ = &cp;
+}
+
+inline void StackTop::unlink(Checkpoint& cp) noexcept
+{
+    if (cp.prev_ != nullptr)
+        cp.prev_->next_ = cp.next_;
+    else
+        cps_ = cp.next_;
+    if (cp.next_ != nullptr)
+        cp.next_->prev_ = cp.prev_;
+}
+
+inline void StackTop::commit_pending() noexcept
+{
+    Checkpoint& cp = *pending_;
+    pending_ = nullptr;
+    link(cp);
+    if (cp.tbl_ != nullptr)
+        ++cp.tbl_[0];
+}
+
+inline void StackTop::relink(Checkpoint& from, Checkpoint& to) noexcept
+{
+    if (&from == pending_)
+    {
+        pending_ = &to;
+        return;
+    }
+    to.prev_ = from.prev_;
+    to.next_ = from.next_;
+    if (to.prev_ != nullptr)
+        to.prev_->next_ = &to;
+    else
+        cps_ = &to;
+    if (to.next_ != nullptr)
+        to.next_->prev_ = &to;
+}
+
+inline void StackTop::adopt(Checkpoint& cp) noexcept
+{
+    link(cp);
+    if (cp.tbl_ != nullptr)
+        ++cp.tbl_[0];
+}
+
+inline void StackTop::forget(Checkpoint& cp) noexcept
+{
+    if (&cp == pending_)
+    {
+        pending_ = nullptr;
+        return;
+    }
+    unlink(cp);
+    if (cp.tbl_ != nullptr)
+        pool_.release(cp.tbl_);
+}
