+/// Detaches every checkpoint and frees all heap memory; arena memory dies with the state.
+inline void StackTop::disown_all() noexcept
+{
+    if (pending_ != nullptr)
+    {
+        pending_->owner_ = nullptr;
+        pending_->tbl_ = nullptr;
+        pending_->height_ = 0;
+        pending_ = nullptr;
+    }
+    for (Checkpoint* cp = cps_; cp != nullptr;)
+    {
+        Checkpoint* next = cp->next_;
+        cp->owner_ = nullptr;
+        cp->tbl_ = nullptr;
+        cp->height_ = 0;
+        cp->prev_ = nullptr;
+        cp->next_ = nullptr;
+        cp = next;
+    }
+    cps_ = nullptr;
+    pool_.free_heap();
+    tbl_ = nullptr;
+    ents_ = nullptr;
+    height = 0;
+    wend_ = 0;
+    cn_ = 0;
+    fend_ = 0;
+    shared_ = false;
+}
