+inline void StackTop::steal(StackTop& o) noexcept
+{
+    height = o.height;
+    ents_ = o.ents_;
+    tbl_ = o.tbl_;
+    wend_ = o.wend_;
+    base_ = o.base_;
+    cn_ = o.cn_;
+    fend_ = o.fend_;
+    shared_ = o.shared_;
