+/// Mark-and-sweep of pages: a page survives if the live table, a checkpoint table or the ring
+/// refers to it.
+inline size_t StackTop::collect() noexcept
+{
+    using namespace stack_detail;
+    if (pending_ != nullptr)
+        commit_pending();
+    uint64_t mark[bitmap_words] = {};
+    const auto visit = [&](uint64_t p) noexcept {
+        if (pool_.in_arena(p))
+        {
+            const size_t b = pool_.block_of(p);
+            mark[b / 64] |= uint64_t{1} << (b % 64);
+        }
+        else if (p != 0)
+            (page_at(p) - 1)[0][1] = 1;
+    };
+    const auto visit_table = [&](const uint64_t* t) noexcept {
+        if (t == nullptr || is_flat(t))
+            return;
+        const uint64_t* e = entries(t);
+        for (size_t i = 0, n = used(t); i < n; ++i)
+            visit(e[i]);
+    };
+    visit_table(tbl_);
+    const uint64_t* last = tbl_;
+    for (const Checkpoint* cp = cps_; cp != nullptr; cp = cp->next_)
+    {
+        if (cp->tbl_ != last)
+            visit_table(cp->tbl_);
+        last = cp->tbl_;
+    }
+    for (uint256* p : pool_.ring)
+        visit(entry_of(p));
+    size_t freed = 0;
+    for (size_t w = 0; w < bitmap_words; ++w)
+    {
+        uint64_t dead = pool_.page_bits[w] & ~mark[w];
+        pool_.page_bits[w] &= mark[w];
+        for (; dead != 0; dead &= dead - 1)
+        {
+            pool_.give(0, w * 64 + static_cast<size_t>(__builtin_ctzll(dead)));
+            ++freed;
+        }
+    }
+    uint256** link = &pool_.heap_pages;
+    while (*link != nullptr)
+    {
+        uint256* raw = *link;
+        if (raw[0][1] != 0)
+        {
+            raw[0][1] = 0;
+            link = reinterpret_cast<uint256**>(&raw[0][0]);
+        }
+        else
+        {
+            *link = reinterpret_cast<uint256*>(raw[0][0]);
+            delete[] raw;
+        }
+    }
+    return freed;
+}
