+inline void StackTop::snapshot(Checkpoint& cp)
+{
+    cp.height_ = height;
+    if (height <= stack_detail::flat_max)
+    {
+        // Shallow stacks are copied: the checkpoint is self-contained and the live stack keeps
+        // its pages writable.
+        if (height != 0)
+            cp.tbl_ = flat_copy();
+        return;
+    }
+    // Deep stacks are shared. The new checkpoint stays pending: it is linked and counted in the
+    // table's reference count on the next mutation (or list operation), keeping this path short.
+    if (pending_ != nullptr)
+        commit_pending();
+    cp.owner_ = this;
+    cp.tbl_ = tbl_;
+    pending_ = &cp;
+    mark_shared();
+}
+
+inline void StackTop::restore(const Checkpoint& cp)
+{
+    if (pending_ != nullptr)
+        commit_pending();
+    if (cp.owner_ == this)
+    {
+        uint64_t* old = tbl_;
+        if (cp.tbl_ != nullptr)
+            ++cp.tbl_[0];
+        tbl_ = cp.tbl_;
+        ents_ = cp.tbl_ != nullptr ? stack_detail::entries(cp.tbl_) : nullptr;
+        height = cp.height_;
+        cn_ = 0;
+        mark_shared();
+        if (old != nullptr)
+            pool_.release(old);
+        return;
+    }
+    if (cp.owner_ == nullptr)
+    {
+        if (cp.tbl_ == nullptr)
+            height = 0;
+        else
+            load_items(stack_detail::flat_items(cp.tbl_), cp.height_);
+        return;
+    }
+    assign_items(cp.tbl_, cp.height_);
+}
